try{navigator.storage&&navigator.storage.persist&&navigator.storage.persist()}catch(e){}
const standalone=()=>!!(navigator.standalone||(window.matchMedia&&matchMedia('(display-mode: standalone)').matches));
async function nbCheck(){const n=state.assets&&state.assets.notebook;if(!n||!n.pages)return{ok:false,count:0,total:0};let ok=0;for(const id of n.pages){try{const m=await kv('get','media:'+id);if(m&&m.blob&&m.blob.size>0)ok++}catch(e){}}return{ok:ok===n.pages.length,count:ok,total:n.pages.length}}
